using TownOfHost;using Csv;using System.Reflection;
class Program {
 static int passed,failed;
 static void Check(bool v,string m="assertion"){if(!v)throw new Exception(m);}
 static void Test(string name,Action a){try{a();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static void Main(){Translator.Init();
 foreach(var key in new string[]{"AbilityUseVote","BakeCatMisidentify","Bloodlust","BloodlustAbilityExposed","BloodlustAbilityTimer","BloodlustDesc","BloodlustInfo","BloodlustInfoLong","BloodlustTimeUntilRed","Cleaner","CleanerButton","CleanerCleanCooldown","CleanerInfo","CleanerInfoLong","CleanerLog","CleanerSyncCooldown","EvilButtoner","EvilButtonerAbilityText","EvilButtonerCanUseMeCall","EvilButtonerInfo","EvilButtonerInfoLong","EvilButtoner_LowerText","Gimlet","GimletButton","GimletDashTime","GimletDashing","GimletDrillCooldown","GimletFriction","GimletFriendlyFire","GimletHitRadius","GimletInfo","GimletInfoLong","GimletSpeed","GuardMasterGuessShield","GuardianGuessShield","GuessShieldBlock","GuessShieldBlocked","GuessShieldNone","GuessShieldReflect","GuesserTellerCannotGuess","Informant","Informant.Informed","Informant.Received","Informant.ReceivedWithName","InformantButton","InformantCooldown","InformantInfo","InformantInfoLong","InformantNeedCount","InformantNotifyTarget","InformantPickReceiver","InformantPickTarget","InformantRevealTarget","InformantSoloWin","InformantTitle","LifeSaver","LifeSaverBarrierMode","LifeSaverButton","LifeSaverCooldown","LifeSaverInfo","LifeSaverInfoLong","LifeSaverUseCount","LifeSaverWinMode","Notice","NoticeInfo","NoticeInfoLong","NoticeNone","NoticePlayer","NoticeRevealRoleMessage","NoticeRevealTeamMessage","NoticeRole","NoticeTeam","NoticeTellEveryone","NoticeTellTeam","Pusher","PusherButton","PusherCooldown","PusherInfo","PusherInfoLong","PusherNoSpot","RulerRuleAllEmptiness","RulerRuleAllWin","Slugger","SluggerAbilityCooldown","SluggerButton","SluggerCanKillWhileCharging","SluggerCantMoveWhileCharging","SluggerChargeTime","SluggerCharged","SluggerCharging","SluggerInfo","SluggerInfoLong","SluggerIsMultiKill","SluggerIsSyncKillCoolTime","SluggerSwingButton","SluggerSwingDelay","SluggerWindup","TairouTellResult","TellResultCrewmate","TellResultImpostor","TellResultRandomRole","WolfBoySeenAsImpostor","WolfBoyTellResult"})foreach(var lang in new[]{SupportedLangs.Japanese,SupportedLangs.English,SupportedLangs.French})
 Test(key+" / "+lang,()=>{var text=Translator.GetString(key,lang);Check(text.Length>0&&!text.Contains("INVALID"),text);});
 Test("all production translation rows unique and 8-column",()=>{using var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("TownOfHost.Resources.string.csv");var rows=CsvReader.ReadFromStream(s,new CsvOptions{HeaderMode=HeaderMode.HeaderPresent}).Where(r=>!r.Values[0].StartsWith("#")).ToArray();Check(rows.All(r=>r.ColumnCount==8));Check(rows.Select(r=>r.Values[0]).Distinct().Count()==rows.Length);});
 Test("Cleaner explicitly documents visible Vanilla body JP",()=>{var t=Translator.GetString("CleanerInfoLong",SupportedLangs.Japanese);Check(t.Contains("Vanilla")&&t.Contains("見た目が残"));});
 Test("Cleaner explicitly documents visible Vanilla body EN",()=>Check(Translator.GetString("CleanerInfoLong",SupportedLangs.English).Contains("remains visible")));
 Test("new role labels are Japanese",()=>{Check(Translator.GetString("Slugger",SupportedLangs.Japanese)=="スラッガー");Check(Translator.GetString("Pusher",SupportedLangs.Japanese)=="突き落とし師");Check(Translator.GetString("Cleaner",SupportedLangs.Japanese)=="クリーナー");Check(Translator.GetString("Gimlet",SupportedLangs.Japanese)=="ギムレット");});
 foreach(string k in new[]{"Destroyer","DestroyerInfo","DestroyerInfoLong","Nova","NovaInfoLong","MadCleaner","MadCleanerInfoLong","Eliminator","EliminatorInfoLong","LessThan","Idol"})Test("existing translation "+k,()=>Check(!Translator.GetString(k,SupportedLangs.Japanese).Contains("INVALID")));
 Console.WriteLine($"HAMO44004_LOCALIZATION_RESULT {passed} passed, {failed} failed (actual Translator and embedded CSV)");Environment.ExitCode=failed==0?0:1;}}
